"""owner 2026-11-24: 計画が空でも安全な札（egg_drop 0）を1枚だけ自動携行する。"""
from docich.hanjuku_speedrun.hanjuku.strategy import kit


def _mem(stock, **extra):
    mem = {'chapter': 3, 'tick': 100, '_records': [], 'card_stock': stock}
    mem.update(extra)
    return mem


def test_a_safe_card_in_stock_is_chosen_and_recorded():
    mem = _mem({'バグストーム': 1})
    assert kit._auto_carry_safe_card(mem, {'step': 's1'}) == 'バグストーム'
    assert any(r.get('decision') == 'cards_autocarried' for r in mem['_records'])


def test_a_card_with_egg_drop_is_never_auto_carried():
    mem = _mem({'ブラッキー': 3})
    assert kit._auto_carry_safe_card(mem, {'step': 's1'}) is None
    assert not mem['_records']


def test_spent_or_dropped_cards_are_not_chosen():
    mem = _mem({'バグストーム': 1}, kit_spent={'s1': ['バグストーム']})
    assert kit._auto_carry_safe_card(mem, {'step': 's1'}) is None
    mem2 = _mem({'バグストーム': 1}, card_drop={'s1': ['バグストーム']})
    assert kit._auto_carry_safe_card(mem2, {'step': 's1'}) is None


def test_no_stock_means_no_auto_carry():
    assert kit._auto_carry_safe_card(_mem({}), {'step': 's1'}) is None
    assert kit._auto_carry_safe_card({'chapter': 3}, {'step': 's1'}) is None
